package org.chenile.jgen.template.chain;

import org.chenile.jgen.provenance.ProvenanceRecorder;
import org.chenile.jgen.template.model.TemplateContext;
import org.chenile.owiz.Command;

import java.nio.file.Files;
import java.nio.file.Path;

/**
 * Writes {@code .jgen/generation.json} into a project generated by a top-level blueprint. A failure here is
 * reported but does not fail generation: the project itself is complete.
 */
public class ProvenanceWriter implements Command<TemplateContext> {
    @Override
    public void execute(TemplateContext context) {
        if (context.isChild() || context.inputSnapshot == null) return;
        try {
            Path project = ProvenanceRecorder.projectDirectory(context.blueprintConfig, context.map);
            if (!Files.isDirectory(project)) {
                System.err.println("Warning: no generation record written; project folder not found: " + project);
                return;
            }
            ProvenanceRecorder.write(context.blueprintConfig, context.config, context.inputSnapshot, project);
        } catch (Exception e) {
            System.err.println("Warning: could not write the JGen generation record: " + e.getMessage());
        }
    }
}
